def rot(a,t):
 a=np.array(a,float);a/=np.linalg.norm(a);x,y,z=a;c=np.cos(t);s=np.sin(t);C=1-c;return np.array([[c+x*x*C,x*y*C-z*s,x*z*C+y*s],[y*x*C+z*s,c+y*y*C,y*z*C-x*s],[z*x*C-y*s,z*y*C+x*s,c+z*z*C]])
def fk(q):
 p=h[0].copy();R=np.eye(3)
 for i in range(7):R=R@rot(axes[i],q[i]);p+=R@(h[i+1]-h[i])
 return p,R
p,R=fk(q);print(q,p,R[:,2]);
for i in range(7):
 qq=q.copy();qq[i]+=.1;pp,rr=fk(qq);print(i+1,'dp/0.1',np.round((pp-p)/.1,3),'dfwd',np.round((rr[:,2]-R[:,2])/.1,3))
